function imgdeleteimage_OnClientClick() {
    document.getElementById('<%=imgThumbImage.ClientID %>').setAttribute("src", "");
    document.getElementById('spanImageTool').style.visibility = 'hidden';
    document.getElementById('<%=hidThumbImagePath.ClientID %>').value = '';
}

function browseThumbImage() {
    var finder = new CKFinder();
    finder.basePath = '<%=InformationCMS.CMSGlobal.AdminRoot %>/ckfinder/';
    finder.selectActionFunction = function(fileUrl) {
        document.getElementById('<%=imgThumbImage.ClientID %>').src = fileUrl;
        document.getElementById('<%=hidThumbImagePath.ClientID %>').value = fileUrl;
        document.getElementById('spanImageTool').style.visibility = 'visible';
    };
    finder.popup();
}

