{
    string strCKPath = hidThumbImagePath.Value.Trim();
    string strFileName = System.IO.Path.GetFileName(strCKPath);
    string strDestPath = strPhysicalInfoImagePath + strFileName;
    if (!System.IO.File.Exists(strDestPath))
    {
        string strSourcePath = Server.MapPath(strCKPath);
        if (System.IO.File.Exists(strSourcePath))
        {
            System.IO.File.Copy(strSourcePath, strDestPath, true);
            DCore.Globals.ResizeImage(strDestPath, 1000, 720);
        }
    }
}

return true;

